var RELAY_BOUND_API_KEY = '32d197234d9674b5e399f6ebe6b3db23';
window.addEventListener('message', function (event) {
  // Require a concrete parent origin; never reflect responses to '*'.
  if (event.source !== window.parent || !event.data || !event.origin) {
    return;
  }
  var requestId =
    event.data && event.data.requestId ? event.data.requestId : '';
  var reply = function (response) {
    window.parent.postMessage(response, event.origin);
  };
  var onError = function (error) {
    // Guarantee a reply even if handleMessage throws/rejects (e.g. storage
    // quota), so the parent RPC fails fast instead of hanging.
    reply({
      requestId: requestId,
      ok: false,
      error: error && error.message ? error.message : 'relay error',
    });
  };
  try {
    // handleMessage returns a response object or a Promise of one
    // (write paths use the async Web Locks API when available).
    Promise.resolve(
      window.RtbtRelay.handleMessage(event.data, RELAY_BOUND_API_KEY),
    )
      .then(reply)
      .catch(onError);
  } catch (error) {
    onError(error);
  }
});
window.parent.postMessage(
  { type: window.RtbtRelay.RELAY_READY_MESSAGE },
  '*',
);
